package com.hmdp.ai.runtime.node;
import com.hmdp.ai.domain.workflow.WorkflowNodeType;import org.springframework.stereotype.Component;import java.util.*;
@Component public class WorkflowNodeRegistry {private final Map<WorkflowNodeType,NodeExecutor>executors;public WorkflowNodeRegistry(List<NodeExecutor>values){Map<WorkflowNodeType,NodeExecutor>m=new EnumMap<>(WorkflowNodeType.class);for(NodeExecutor e:values)for(WorkflowNodeType t:e.supportedTypes())if(m.put(t,e)!=null)throw new IllegalStateException("duplicate node executor: "+t);for(WorkflowNodeType t:WorkflowNodeType.values())if(!m.containsKey(t))throw new IllegalStateException("missing node executor: "+t);executors=Collections.unmodifiableMap(m);}public NodeExecutor require(WorkflowNodeType type){return executors.get(type);}}
